        i = ins[k]
        c = carg[k - i0]
        op = i.op
        if op in (Oargsb, Oargub, Oparsb, Oparub, Oargsh, Oarguh, Oparsh, Oparuh,
                  Opar, Oarg):
            if op in (Oargsb, Oargub, Oparsb, Oparub):
                c.size = 1
            elif op in (Oargsh, Oarguh, Oparsh, Oparuh):
                c.size = 2
            else:
                c.size = 8
