def selcall(fn, ins, i0, i1, il):
    ca = [Class() for _ in range(i1 - i0)]
    cty = argsclass(ins, i0, i1, ca)
    stk = 0
    for k in range(i0, i1):
        i = ins[k]
        c = ca[k - i0]
        if c.class_ & Cptr:
            i.arg[0] = newtmp("abi", Kl, fn)
            stkblob(i.arg[0], c, fn, il)
            i.op = Oarg
