def selpar(fn, i0, i1):
    ins = fn.start.ins
    ca = [Class() for _ in range(i1 - i0)]
    D.curi = NIns
    cty = argsclass(ins, i0, i1, ca)
    fn.reg = arm64_argregs(CALL(cty), None)
    il = []
    tmp = [R] * 16
    t = 0
    for k in range(i0, i1):
        i = ins[k]
        c = ca[k - i0]
        if i.op != Oparc or (c.class_ & (Cptr | Cstk)):
            continue
