        if KBASE(k) == 0 and phi:
            return
        if KBASE(k) == 1 and c.type == CBits:
            pa[pi] = fconref(c.i, k, fn)
            return
        r1 = newtmp("isel", k, fn)
        if KBASE(k) == 0:
            emit(Ocopy, k, r1, r0, R)
        else:
            n = _stashbits(c.i, 8 if KWIDE(k) else 4)
            ci = _newfpcon(n, fn)
            r2 = newtmp("isel", Kl, fn)
            emit(Oload, k, r1, r2, R)
            emit(Ocopy, Kl, r2, CON(ci), R)
