    if isload(i.op):
        foldaddr(i.arg, 0, accsize(i), fn)
    if isstore(i.op):
        foldaddr(i.arg, 1, accsize(i), fn)
    emiti(i)
    iarg = D.insb[D.curi].arg
    fixarg(iarg, 0, argcls(i, 0), 0, fn)
    fixarg(iarg, 1, argcls(i, 1), 0, fn)
