    b = fn.start
    al = Oalloc
    n = 4
    while al <= Oalloc1:
        for i in b.ins[:b.nins]:
            if i.op == al:
                if rtype(i.arg[0]) != RCon:
                    break
                sz = fn.con[rval(i.arg[0])].i
                if sz < 0 or sz >= 0x7fffffff - 15:
                    err("invalid alloc size %d", sz)
                sz = (sz + n - 1) & -n
                sz //= 4
                fn.tmp[rval(i.to)].slot = fn.slot
                fn.slot += sz
                i.set(Ins(Onop))
        al += 1
        n *= 2
