    b = fn.start.link
    while True:
        if not b:
            b = fn.start
        D.curi = NIns
        for sb in (b.s1, b.s2):
            if not sb:
                break
            p = sb.phi
            while p:
                n = 0
                while p.blk[n] is not b:
                    assert n + 1 < p.narg
                    n += 1
