def foldflt(res, op, w, cl, cr):
    if cl.type != CBits or cr.type != CBits:
        err("invalid address operand for '%s'", optab[op].name)
    res.type = CBits
    res.sym = Sym()
    res.i = 0
    res.flt = 0
