    latebid = NOBID
    for k in range(t.nuse):
        u = t.use[k]
        assert u.bid < fn.nblk
        b = fn.rpo[u.bid]
        if u.type == UPhi:
            uselatebid = latephi(fn, u.u, r)
        elif u.type == UIns:
            uselatebid = lateins(fn, b, u.u, r)
        elif u.type == UJmp:
            uselatebid = latejmp(b, r)
