    i0, i1 = igroup(b, k)
    for k in range(i0, i1):
        i = b.ins[k]
        for n in range(2):
            if rtype(i.arg[n]) != RTmp:
                continue
            t = fn.tmp[rval(i.arg[n])]
            if t.bid != b.id or not t.def_:
                continue
