import sys
from . import defs as D
from . import copy as C
from .defs import (R, RTmp, CON_Z, CBits, Con, Ins, KBASE, KWIDE, U32, Kx, Kw, Kl, UXXX,
                   UPhi, UIns, UJmp, Jjmp, Jjnz, Onop, Osub, Oadd, Osel0, optab, rtype,
                   rval, rkind, s32)
