    if rtype(r2) == RTmp:
        t2 = fn.tmp[rval(r2)]
    b = fn.rpo[u.bid]
    if u.type == UPhi:
        p = u.u
        for n in range(p.narg):
            if p.arg[n] == r1:
                p.arg[n] = r2
