def rebuildcfg(fn):
    nblk = fn.nblk
    rpo = list(fn.rpo[:nblk])
    fillcfg(fn)
    s = fn.start
    for n in range(nblk):
        b = rpo[n]
        if b.id != U32:
            continue
        assert b is not s
        for i in b.ins[:b.nins]:
            if not optab[i.op].pinned:
                if gvndup(i, 0) is i:
                    addins(s, i)
def gvn(fn):
    global gvntbl, gvntbln
    from .ssa import filluse, ssacheck
    from .parse import printfn
    con01[0] = getcon(0, fn)
    con01[1] = getcon(1, fn)
