        T.abi0(fn)
        cfg.fillcfg(fn)
        ssa.filluse(fn)
        mem.promote(fn)
        ssa.filluse(fn)
        ssa.ssa(fn)
        ssa.filluse(fn)
        ssa.ssacheck(fn)
        alias.fillalias(fn)
        load.loadopt(fn)
        ssa.filluse(fn)
        alias.fillalias(fn)
        mem.coalesce(fn)
        ssa.filluse(fn)
        cfg.filldom(fn)
        ssa.ssacheck(fn)
        gvn.gvn(fn)
        cfg.fillcfg(fn)
        cfg.simplcfg(fn)
        ssa.filluse(fn)
        cfg.filldom(fn)
        gcm.gcm(fn)
        ssa.filluse(fn)
        ssa.ssacheck(fn)
        from .. import middle
        if middle.enabled:
            cfg.filldom(fn)
            if middle.run(fn):
                ssa.ssacheck(fn)
                gvn.gvn(fn)
                cfg.fillcfg(fn)
                cfg.simplcfg(fn)
                ssa.filluse(fn)
                cfg.filldom(fn)
