        i = b.ins[ii]
        if i.op == Oblit0:
            so = slot(i.arg[0], fn, sl)
            if so:
                s, off0 = so
                so0 = slot(i.arg[1], fn, sl)
                if so0:
                    s0, off1 = so0
                    if s.s is s0.s:
                        i1 = b.ins[ii + 1]
