def _fmtf(x):
    if x != x:
        return '-nan' if math.copysign(1.0, x) < 0 else 'nan'
    return '%f' % x
def printcon(c, f):
    if c.type == CUndef:
        pass
    elif c.type == CAddr:
        if c.sym.type & SExt:
            f.write("extern ")
        if c.sym.type & SThr:
            f.write("thread ")
        f.write("$%s" % str_(c.sym.id))
        if c.i:
            f.write("%+d" % c.i)
    elif c.type == CBits:
        if c.flt == 1:
            f.write("s_%s" % _fmtf(c.s))
        elif c.flt == 2:
            f.write("d_%s" % _fmtf(c.d))
        else:
            f.write("%d" % c.i)
def printref(r, fn, f):
    rt = rtype(r)
    if rt == RTmp:
        if rval(r) < Tmp0:
            f.write("R%d" % rval(r))
        else:
            f.write("%%%s" % fn.tmp[rval(r)].name)
    elif rt == RCon:
        if req(r, UNDEF):
            f.write("UNDEF")
        else:
            printcon(fn.con[rval(r)], f)
    elif rt == RSlot:
        f.write("S%d" % rsval(r))
    elif rt == RCall:
        f.write("%04x" % rval(r))
    elif rt == RType:
        f.write(":%s" % D.typ[rval(r)].name)
    elif rt == RMem:
        i = 0
        m = fn.mem[rval(r)]
        f.write('[')
        if m.offset.type != CUndef:
            printcon(m.offset, f)
            i = 1
        if not req(m.base, R):
            if i:
                f.write(" + ")
            printref(m.base, fn, f)
            i = 1
        if not req(m.index, R):
            if i:
                f.write(" + ")
            f.write("%d * " % m.scale)
            printref(m.index, fn, f)
        f.write(']')
    elif rt == RInt:
        f.write("%d" % rsval(r))
    elif rt == -1:
        f.write("R")
