    for n in range(m.n):
        t = m.t[n]
        s = tmp[t].slot
        r1 = m.r[n]
        r = rfind(m0, t)
        if r != -1:
            pmadd(TMP(r1), TMP(r), tmp[t].cls)
        elif s != -1:
            pmadd(TMP(r1), SLOT(s), tmp[t].cls)
