        while b:
            a = 0
            while a < b.npred:
                if b.id <= b.pred[a].id:
                    break
                a += 1
            if a != b.npred:
                err.write("\\t%-10s" % b.name)
                err.write(" (% 3d " % b.nlive[0])
                err.write("% 3d) " % b.nlive[1])
