            t = fn.tmp[rval(p.to)]
            tmpuse(p.to, 0, 0, fn)
            for a in range(p.narg):
                n = p.blk[a].loop
                t.cost = (t.cost + n) & U32
                tmpuse(p.arg[a], 1, n, fn)
