    v = BSet()
    w = BSet()
    bsinit(u, ntmp)
    bsinit(v, ntmp)
    bsinit(w, ntmp)
    bsinit(mask[0], ntmp)
    bsinit(mask[1], ntmp)
    locs = fn.slot
    slot4 = 0
    slot8 = 0
