    while b:
        p = b.phi
        while p:
            assert rtype(p.to) == RTmp
            tp = rval(p.to)
            tmp[tp].bid = b.id
            tmp[tp].ndef += 1
            tmp[tp].cls = p.cls
            tp = phicls(tp, fn.tmp)
            for a in range(p.narg):
                if rtype(p.arg[a]) == RTmp:
                    t = rval(p.arg[a])
