def cmpop(c):
    assert 0 <= c < NCmp
    return _cmptab[c][1]
def cmpwlneg(op):
    if Ocmpw <= op <= Ocmpw1:
        return _cmptab[op - Ocmpw][0] + Ocmpw
    if Ocmpl <= op <= Ocmpl1:
        return _cmptab[op - Ocmpl][0] + Ocmpl
    die("not a wl comparison")
def clsmerge(k1, k):
    if k1 == Kx:
        return k, 0
    if (k1 == Kw and k == Kl) or (k1 == Kl and k == Kw):
        return Kw, 0
    return k1, int(k1 != k)
def phicls(t, tmp):
    t1 = tmp[t].phi
    if not t1:
        return t
    t1 = phicls(t1, tmp)
    tmp[t].phi = t1
    return t1
def phiargn(p, b):
    if p:
        for n in range(p.narg):
            if p.blk[n] is b:
                return n
    return U32
def phiarg(p, b):
    n = phiargn(p, b)
    assert n != U32, "block not found"
    return p.arg[n]
_newtmp_n = 0
def newtmp(prfx, k, fn):
    global _newtmp_n
    t = fn.ntmp
    fn.ntmp += 1
    vgrow(fn.tmp, fn.ntmp)
    tm = Tmp()
    fn.tmp[t] = tm
    if prfx:
        _newtmp_n += 1
        tm.name = "%s.%d" % (prfx, _newtmp_n)
    tm.cls = k
    tm.slot = -1
    tm.nuse = 1
    tm.ndef = 1
    return TMP(t)
def chuse(r, du, fn):
    if rtype(r) == RTmp:
        fn.tmp[rval(r)].nuse += du
def symeq(s0, s1):
    return s0.type == s1.type and s0.id == s1.id
def newcon(c0, fn):
    for i in range(1, fn.ncon):
        c1 = fn.con[i]
        if c0.type == c1.type and symeq(c0.sym, c1.sym) and c0.i == c1.i:
            return CON(i)
    i = fn.ncon
    fn.ncon += 1
    vgrow(fn.con, fn.ncon, Con)
    fn.con[i] = c0.copy()
    return CON(i)
def getcon(val, fn):
    for c in range(1, fn.ncon):
        if fn.con[c].type == CBits and fn.con[c].i == val:
            return CON(c)
    c = fn.ncon
    fn.ncon += 1
    vgrow(fn.con, fn.ncon, Con)
    fn.con[c] = Con(CBits, val)
    return CON(c)
def addcon(c0, c1, m):
    if m != 1 and c1.type == CAddr:
        return 0
    if c0.type == CUndef:
        c0.set(c1)
        c0.i = s64(c0.i * m)
    else:
        if c1.type == CAddr:
            if c0.type == CAddr:
                return 0
            c0.type = CAddr
            c0.sym = c1.sym.copy()
        c0.i = s64(c0.i + c1.i * m)
    return 1
def isconbits(fn, r):
    if rtype(r) == RCon:
        c = fn.con[rval(r)]
        if c.type == CBits:
            return c.i
    return None
def salloc(rt, rs, fn):
    fn.dynalloc = 1
    if rtype(rs) == RCon:
        sz = fn.con[rval(rs)].i
        if sz < 0 or sz >= 0x7fffffff - 15:
            err("invalid alloc size %d", sz)
        sz = (sz + 15) & -16
        emit(Osalloc, Kl, rt, getcon(sz, fn), R)
    else:
        r0 = newtmp("isel", Kl, fn)
        r1 = newtmp("isel", Kl, fn)
        emit(Osalloc, Kl, rt, r0, R)
        emit(Oand, Kl, r0, r1, getcon(-16, fn))
        emit(Oadd, Kl, r1, rs, getcon(15, fn))
