        self.relocs.append((len(self.c), ADDR if wide else ADDR32, name, addend))
        if wide:
            self.c += bytes([0x23, G_MEM, 0xAD, 0x42]) + sleb5(0) + bytes([0x7C])
        else:
            self.c += bytes([0x23, G_MEM, 0x41]) + sleb5(0) + bytes([0x6A])
