    both = not v.get('modules') and not v.get('runtime')
    mods, rts = _cache_entries()
    freed = 0
    nm = nr = 0
    if both or v.get('modules'):
        for p, n in mods:
            try:
                os.remove(p)
                freed += n
                nm += p.endswith('.s')
            except OSError:
                pass
