def parseinit(s, t):
    p = InitParser()
    p.obj = [Object() for _ in range(NOBJ)]
    p.cur = None
    p.sub = 0
    p.obj[0].offset = 0
    p.obj[0].type = t
    p.obj[0].iscur = False
    p.init = None
    p.last = None
    if t.incomplete and t.kind != TYPEARRAY:
        error(tok.loc, "initializer specified for incomplete type")
