def mkfunc(decl, name, t, s):
    f = Func()
    f.decl = decl
    f.name = name
    f.type = t
    f.start = f.end = mkblock("start")
    f.lastid = 0
    f.gotos = {}
    emittype(t.base)
    f.paramtemps = []
    d = t.params
    while d:
        v = Value()
        f.paramtemps.append(v)
        emittype(d.type)
        functemp(f, v)
        if d.name:
            if d.type.value:
                d.value = v
            else:
                funcalloc(f, d)
                funcstore(f, d.type, QUALNONE, LValue(d.value), v)
        d = d.next
