    k = e.kind
    if k == EXPRIDENT:
        d = e.decl
        if d.kind != DECLOBJECT and d.kind != DECLFUNC:
            error(tok.loc, "identifier '%s' is not an object or function", d.name)
        if d is f.namedecl:
            w("data ")
            emitname(d.value)
