def funcbranch(f, e, bt, bf):
    k = e.kind
    if k == EXPRBINARY:
        l = e.l
        r = e.r
        op = e.op
        if op == TEQL or op == TNEQ:
            r = EV.eval(r)
            if r.kind == EXPRCONST and r.type.prop & PROPINT and r.u == 0:
                if e.op == TEQL:
                    bt, bf = bf, bt
                funcbranch(f, l, bt, bf)
                return _one
        elif op == TLOR or op == TLAND:
            if e.op == TLOR:
                b = mkblock("logic_or")
                funcbranch(f, l, bt, b)
            else:
                b = mkblock("logic_and")
                funcbranch(f, l, b, bf)
            funclabel(f, b)
            funcbranch(f, r, bt, bf)
            return _one
    elif k == EXPRCOMMA:
        e = e.base
        while e.next:
            funcexpr(f, e)
            e = e.next
