    spec = _BUILTINS.get(d.name)
    if spec is None or d.kind != DECLFUNC or d.linkage != LINKEXTERN or d.asmname:
        return None
    op, nargs, size = spec
    t = TY.typedouble if size == 8 else TY.typefloat
