    if ft.base is not t or ft.isvararg or e.type is not t:
        return None
    p = ft.params
    args = []
    arg = e.args
    for _ in range(nargs):
        if not p or p.type is not t or not arg or arg.type is not t:
            return None
        args.append(arg)
        p = p.next
        arg = arg.next
    if p or arg:
        return None
