    T4 = ef.op(D.Oand, Kl, T, ef.con(-U)) if U > 1 else T
    end4 = ef.add(kc, ctlg.init, ef.mulc(kc, T4, ctlg.S.c))
    end = ef.add(kc, ctlg.init, ef.mulc(kc, T, ctlg.S.c))
