    for t in sorted(used):
        if t not in liveout:
            raise AssertionError('live-out without fast value')
        cls = fn.tmp[t].cls
        v = newtmp('m', cls, fn)
        ir.addphi(X, cls, v, [(H, D.TMP(t)), (FX, liveout[t])])
