def _used_outside(fn, lp, newblocks):
    ids = set()
    for b in ir.blocks(fn):
        if b in lp.blocks or b in newblocks:
            continue
        refs = []
        for p in ir.phis(b):
            refs.extend(p.arg[:p.narg])
        for i in ir.ins(b):
            refs.extend(i.arg)
        refs.append(b.jmp.arg)
        for r in refs:
            if ir.istmp(r) and fn.tmp[rval(r)].bid == lp.header.id:
                ids.add(rval(r))
