    from .. import linker as L
    c = L.user_cache('CIMO_CACHE_DIR')
    if c:
        p = os.path.join(c, key + '.wasm')
        try:
            with open(p + '.sig.tmp', 'w') as f:
                f.write(sigs)
            os.replace(p + '.sig.tmp', p + '.sig')
            with open(p + '.tmp', 'wb') as f:
                f.write(mod)
            os.replace(p + '.tmp', p)
            return
        except OSError:
            pass
