def _bootstrap(files):
    import builtins
    import linecache
    import os
    import sys
    import types
    from importlib.abc import Loader, MetaPathFinder
    from importlib.machinery import ModuleSpec

    root = '<%s>/cimo' % os.path.basename(__file__)

    class BundleLoader(MetaPathFinder, Loader):
        """Serves cimo.* from the table; cimo.resources reads package files from it."""
        bundle_files = files
        bundle_root = root

        def _find(self, fullname):
            if fullname == 'cimo':
                return '__init__.py', True
            if not fullname.startswith('cimo.'):
                return None, False
            rel = fullname[5:].replace('.', '/')
            if rel + '/__init__.py' in files:
                return rel + '/__init__.py', True
            if rel + '.py' in files:
                return rel + '.py', False
            return None, False

        def find_spec(self, fullname, path=None, target=None):
            rel, pkg = self._find(fullname)
            if rel is None or fullname == 'cimo':
                return None
            spec = ModuleSpec(fullname, self, origin=root + '/' + rel, is_package=pkg)
            spec.has_location = True
            return spec

        def create_module(self, spec):
            return None

        def exec_module(self, module):
            exec(self.get_code(module.__name__), module.__dict__)

        def get_code(self, fullname):
            return code(self._find(fullname)[0])

        def get_source(self, fullname):
            return files.get(self._find(fullname)[0])

    def code(rel):
        # registered with linecache: tracebacks show <cimo.py>/cimo/driver.py and its lines
        filename = root + '/' + rel
        src = files[rel]
        linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
        return builtins.compile(src, filename, 'exec', dont_inherit=True)  # not cimo.compile

    loader = BundleLoader()
    if __name__ == 'cimo':
        pkg = sys.modules['cimo']
    else:  # run as a script, or imported under another name: make the package `cimo`
        pkg = sys.modules['cimo'] = types.ModuleType('cimo')
        pkg.__file__ = __file__
        pkg.__spec__ = ModuleSpec('cimo', loader, origin=__file__)
    pkg.__path__ = pkg.__spec__.submodule_search_locations = []
    pkg.__package__ = 'cimo'
    sys.meta_path.insert(0, loader)
    try:
        exec(code('__init__.py'), pkg.__dict__)
    except BaseException:
        sys.meta_path.remove(loader)
        raise
    return pkg


_cimo = _bootstrap(_FILES)
if __name__ == '__main__':
    import runpy
    runpy.run_module('cimo', run_name='__main__', alter_sys=True)
elif __name__ != 'cimo':
    import sys
    sys.modules[__name__] = _cimo
else:
    del _bootstrap, _cimo, _FILES
